def solve_kth_repeat(text):
    tokens = text.split()
    n, k = int(tokens[0]), int(tokens[1])
    counts = {}
    for oid in tokens[2:2 + n]:
        counts[oid] = counts.get(oid, 0) + 1
        if counts[oid] == k:
            return oid
    return 'NONE'
